# Exact normalized title, description, or nonempty brand values.
def exact_normalized(r):
    import re
    import unicodedata
    import hashlib

    def norm(value):
        value = unicodedata.normalize("NFKD", value or "")
        value = "".join(c for c in value if not unicodedata.combining(c)).casefold()
        value = re.sub(r"[\W_]+", " ", value, flags=re.UNICODE)
        words = re.findall(r"[^\W_]+", value, flags=re.UNICODE)
        out = []
        for word in words:
            if not out or word != out[-1]:
                out.append(word)
        return " ".join(out)

    def key(prefix, value):
        return prefix + hashlib.blake2s(value.encode("utf-8"), digest_size=8).hexdigest()

    keys = []
    title = norm(r.get("title", ""))
    brand = norm(r.get("brand", ""))
    description = norm(r.get("description", ""))
    if title:
        keys.append(key("et:", title))
    if brand:
        keys.append(key("eb:", brand))
    if description:
        keys.append(key("ed:", description))
    return keys


# Punctuation-tolerant model identifiers and distinctive lexical anchors from all textual attributes.
def identifier_and_anchor(r):
    import re
    import unicodedata
    import hashlib

    def norm(value):
        value = unicodedata.normalize("NFKD", value or "")
        value = "".join(c for c in value if not unicodedata.combining(c)).casefold()
        return re.sub(r"[^\w]+", " ", value, flags=re.UNICODE).strip()

    text = " ".join(norm(r.get(name, "")) for name in ("title", "brand", "description"))
    tokens = re.findall(r"[^\W_]+", text, flags=re.UNICODE)
    candidates = {}

    for match in re.finditer(
        r"(?<!\w)(?=[a-z0-9._/+:-]{4,}\b)(?=[a-z0-9._/+:-]*[a-z])"
        r"(?=[a-z0-9._/+:-]*\d)[a-z0-9]+(?:[._/+:-][a-z0-9]+)*(?!\w)",
        unicodedata.normalize("NFKC", " ".join(
            r.get(name, "") or "" for name in ("title", "brand", "description")
        )).casefold()
    ):
        compact = re.sub(r"[^a-z0-9]", "", match.group())
        if len(compact) >= 4:
            score = 100 + min(len(compact), 30) + 4 * sum(c.isdigit() for c in compact)
            candidates[compact] = max(candidates.get(compact, 0), score)

    for token in tokens:
        if len(token) >= 5:
            digits = sum(c.isdigit() for c in token)
            transitions = sum(token[i].isdigit() != token[i - 1].isdigit()
                              for i in range(1, len(token)))
            score = min(len(token), 24) + 8 * digits + 5 * transitions
            candidates[token] = max(candidates.get(token, 0), score)

    chosen = sorted(candidates, key=lambda x: (-candidates[x], -len(x), x))[:3]
    return [
        "ia:" + hashlib.blake2s(value.encode("utf-8"), digest_size=7).hexdigest()
        for value in chosen
    ]


# Character-level MinHash signatures tolerate reordered wording, spelling noise, and retailer additions.
def fuzzy_character_signature(r):
    import re
    import unicodedata
    import hashlib

    def norm(value):
        value = unicodedata.normalize("NFKD", value or "")
        value = "".join(c for c in value if not unicodedata.combining(c)).casefold()
        return re.sub(r"[^a-z0-9]+", "", value)

    parts = [norm(r.get("title", "")), norm(r.get("brand", ""))]
    text = "".join(parts)
    if not text:
        text = norm(r.get("description", ""))
    if not text:
        return []

    width = 5 if len(text) >= 12 else max(2, len(text) // 2)
    shingles = {text[i:i + width] for i in range(max(1, len(text) - width + 1))}
    if not shingles:
        shingles = {text}

    keys = []
    for salt in (b"\x11", b"\x53", b"\x97"):
        minimum = min(
            hashlib.blake2s(salt + shingle.encode("utf-8"), digest_size=8).digest()
            for shingle in shingles
        )
        keys.append("fc:" + salt.hex() + minimum[:6].hex())
    return keys


# Coarse structural and measurement keys provide fallback for sparse, translated, or severely corrupted records.
def sparse_measurement_fallback(r):
    import re
    import unicodedata
    import hashlib

    def fold(value):
        value = unicodedata.normalize("NFKD", value or "")
        value = "".join(c for c in value if not unicodedata.combining(c)).casefold()
        return re.sub(r"\s+", " ", value)

    def short(prefix, value):
        return prefix + hashlib.blake2s(value.encode("utf-8"), digest_size=6).hexdigest()

    title = fold(r.get("title", ""))
    all_text = " ".join(fold(r.get(name, "")) for name in
                        ("title", "brand", "description", "price"))
    title_words = re.findall(r"[^\W_]+", title, flags=re.UNICODE)
    count_bucket = (len(title_words) + 4) // 8
    keys = ["sc:" + str(count_bucket)]

    unit_family = {
        "b": "storage", "kb": "storage", "mb": "storage", "gb": "storage",
        "tb": "storage", "pb": "storage", "kib": "storage", "mib": "storage",
        "gib": "storage", "tib": "storage", "pib": "storage",
        "hz": "frequency", "khz": "frequency", "mhz": "frequency", "ghz": "frequency",
        "mm": "length", "cm": "length", "m": "length",
        "mah": "charge", "wh": "energy", "w": "power", "v": "voltage",
        "mp": "resolution", "rpm": "rotation",
    }
    found = set()
    pattern = r"(?<!\w)(\d+(?:[.,]\d+)?)\s*(kib|mib|gib|tib|pib|kb|mb|gb|tb|pb|khz|mhz|ghz|mah|rpm|hz|mm|cm|mp|wh|b|m|w|v)\b"
    for number, unit in re.findall(pattern, all_text):
        digits = re.sub(r"\D", "", number)
        significant = digits.lstrip("0")
        if significant:
            significant = significant[:2]
            found.add(unit_family[unit] + ":" + significant)

    for value in sorted(found)[:2]:
        keys.append(short("ms:", value))
    return keys


